$_MODULE['<{amazonmarketplacepro}prestashop>configure_c37fbb2c2feddaecff0e108da07ec026'] = 'Adresy przekierowujące Amazon wygasają po pewnym czasie; adres syntetyczny zapobiega odbijaniu się wiadomości sklepu. Kontakt z kupującym przez Amazon nadal działa.';
$_MODULE['<{amazonmarketplacepro}prestashop>configure_af6dd5c53d00465bccc957cc7b971ba0'] = 'Usuwaj dane kupującego po';
$_MODULE['<{amazonmarketplacepro}prestashop>configure_07e932ebe6b3a0cfb938682b7f857e92'] = 'Polityka ochrony danych Amazon wymaga usunięcia danych kupującego w ciągu 30 dni od dostawy. Gdy zamówienie jest zakończone i starsze niż ten okres, moduł czyści z własnej tabeli imię i nazwisko, e-mail, ulicę, miasto, region, kod pocztowy i telefon kupującego oraz zapisane dane z Amazon. Kwoty zamówienia, podatki, prowizje i kraj docelowy pozostają, więc raporty i ewidencja VAT nie ulegają zmianie.';
$_MODULE['<{amazonmarketplacepro}prestashop>configure_c9274fdfe06e9b2c44c404eea92a96f1'] = 'zamówienie(-a) oczekujące na wyczyszczenie;';
