$_MODULE['<{amazonmarketplacepro}prestashop>configure_4ab9e6c00c5055c58feffff5ae55cd84'] = 'Włączone (wymagane przez zasady Amazon)';
$_MODULE['<{amazonmarketplacepro}prestashop>configure_d15305d7a4e34e02489c74a5ef542f36'] = 'Wyłączone';
$_MODULE['<{amazonmarketplacepro}prestashop>configure_9a89fce15c653813bba97088f4242469'] = 'Wyłączenie tej opcji oznacza przechowywanie danych kupujących z Amazon dłużej, niż Amazon na to pozwala. Zrób to tylko wtedy, gdy wymaga tego obowiązek prawny, który potrafisz wskazać.';
$_MODULE['<{amazonmarketplacepro}prestashop>configure_114fc58e687755f400c4ff77e00b9cf7'] = 'Anonimizuj także klienta i adres w PrestaShop';
$_MODULE['<{amazonmarketplacepro}prestashop>configure_06d16f3c4536d713eafb1f97f25657f4'] = 'Nie (zalecane)';
$_MODULE['<{amazonmarketplacepro}prestashop>configure_b3a631ecd8088b96eeab29ebb7670789'] = 'Celowo domyślnie wyłączona. PrestaShop tworzy faktury na podstawie zapisanego adresu, więc jego anonimizacja zmienia dokumenty, które prawo może nakazywać przechowywać w nienaruszonej postaci — a faktura, którą musisz zachować, to dokładnie wyjątek dopuszczony przez politykę Amazon. Włącz tę opcję dopiero po zasięgnięciu własnej porady prawnej. Gdy jest włączona, klient jest anonimizowany tylko wtedy, gdy wszystkie jego zamówienia są zamówieniami Amazon już wyczyszczonymi; miasto, kod pocztowy i kraj pozostają, aby rozliczenie VAT dało się uzasadnić.';
$_MODULE['<{amazonmarketplacepro}prestashop>configure_4afb955a8ca5e46fdaf13febfabde9b0'] = 'Grupa klientów dla kupujących z Amazon';
$_MODULE['<{amazonmarketplacepro}prestashop>configure_650e8746625f41e4234739e9894cbb78'] = '-- Domyślnie w sklepie --';
$_MODULE['<{amazonmarketplacepro}prestashop>configure_67b7390afec4abee3eaecd923f291c15'] = 'Zdalny koszyk (rezerwacja towaru dla nieopłaconych zamówień)';
$_MODULE['<{amazonmarketplacepro}prestashop>configure_f9f2d03af364aa656f60472f050f5ce9'] = 'Amazon pokazuje trwający zakup jako zamówienie w stanie „Pending”. Przy włączonej opcji moduł od razu zdejmuje te sztuki ze stanu PrestaShop, aby żaden inny kanał nie mógł ich sprzedać, i zwraca je, jeśli zamówienie nigdy nie stanie się płatne. Wymaga importu zamówień Pending — moduł robi to automatycznie po włączeniu opcji — oraz crona remote_cart do rozliczania rezerwacji.';
$_MODULE['<{amazonmarketplacepro}prestashop>configure_606e569ed905da68a3f26de02575c6d9'] = 'Zwalniaj rezerwację po';
$_MODULE['<{amazonmarketplacepro}prestashop>configure_4e9a4f12657cf4a16631d3bfbbd3ea93'] = 'Okres karencji, zanim towar z zamówienia wciąż utkniętego w stanie Pending wróci na stan. 4 godziny to bezpieczna wartość — Amazonowi zmiana statusu na Unshipped może chwilę zająć.';
$_MODULE['<{amazonmarketplacepro}prestashop>configure_a2d4829bd7afcb0622263a02a3b7a5fc'] = 'Zamówienia bez wystarczającego stanu';
$_MODULE['<{amazonmarketplacepro}prestashop>configure_64f05d6bfbce6140c765c29e952478b7'] = 'Mimo to utwórz zamówienie PS';
