$_MODULE['<{amazonmarketplacepro}prestashop>configure_12dbd64f2bc9a6277ee7b95e9a2349dd'] = 'Kierowanie importowanych zamówień';
$_MODULE['<{amazonmarketplacepro}prestashop>configure_5cbc8ff529ecab618089ef063e3be9d2'] = 'Amazon podaje szybkość dostawy obiecaną kupującemu. Przypisz każdą z nich do przewoźnika PrestaShop, aby importowane zamówienia miały właściwą metodę wysyłki; nieprzypisane trafią do domyślnego przewoźnika powyżej.';
