$_MODULE['<{amazonmarketplacepro}prestashop>configure_f3604b94532854eabcb2fe73cad7f865'] = 'Dodaj tę jedną linię w panelu hostingu lub w crontabie. Między sklepem a jego harmonogramem nie ma wtedy nic pośredniego — dlatego to rozwiązanie zalecamy.';
$_MODULE['<{amazonmarketplacepro}prestashop>configure_b1481f64dd0ca696a1845d6585cb098b'] = 'Każde wywołanie uruchamia tylko to, co tabela poniżej wskazuje jako należne, więc cron co pięć minut nie oznacza synchronizacji co pięć minut.';
$_MODULE['<{amazonmarketplacepro}prestashop>configure_0cd2f5c5335a77f8d7c4522d414014dd'] = 'Dla hostingów bez crontaba. Nasz serwer wywołuje Twój sklep co pięć minut, dzięki czemu Twoje interwały są dotrzymywane co do minuty, a Ty nie musisz nic konfigurować.';
$_MODULE['<{amazonmarketplacepro}prestashop>configure_faa4a350ec0dc4e558f827d5cdf6c2db'] = 'Dwie rzeczy warto wiedzieć przed wyborem tej opcji. Adres Twojego sklepu i jego token crona są przechowywane na naszym serwerze, ponieważ to właśnie ten token pozwala wywołaniu rozpocząć przebieg. A jeśli nasz serwer będzie nieosiągalny, harmonogram zatrzyma się do czasu jego powrotu.';
