$_MODULE['<{amazonmarketplacepro}prestashop>configure_2d0e5660bea8a218a576ac7526dad77b'] = 'Jeśli chcesz jedynie tymczasowo wstrzymać sprzedaż, opublikowanie ilości 0 (domyślne ustawienia ofert) zachowuje ofertę i jej opinie.';
