$_MODULE['<{amazonmarketplacepro}prestashop>configure_46d9cde3daffdb463a8e3cca14a15d8e'] = 'Opcjonalne. Dla produktów, które Amazon już sprzedaje, odnajduje istniejącą stronę po numerze EAN, dzięki czemu dodajesz do niej ofertę zamiast tworzyć duplikat.';
$_MODULE['<{amazonmarketplacepro}prestashop>configure_76fe281cff4e7e7292b1c1a68add27b3'] = 'Wyślij do Amazon';
$_MODULE['<{amazonmarketplacepro}prestashop>configure_c60fbb93366c2db82e7f15b891519249'] = 'Wysyła to, co porównanie oznacza jako oczekujące. Do 25 SKU idzie pojedynczo i otrzymuje natychmiastową odpowiedź; więcej wysyłanych jest jako jeden feed, który śledzisz w sekcji Stan feedu.';
