$_MODULE['<{amazonmarketplacepro}prestashop>configure_123999c78f3b0fb3c2882359df62183a'] = 'Przenieś oferty z Amazon do PrestaShop. Pierwszy krok tylko odczytuje i porównuje; w drugim wybierasz, co zapisać, po obejrzeniu tabeli.';
$_MODULE['<{amazonmarketplacepro}prestashop>configure_7a39a1aacfcb9ac0960364ad6017a5ce'] = 'Synchronizuj Amazon do PS';
$_MODULE['<{amazonmarketplacepro}prestashop>configure_ac2360e03b18358b7be754f743139fed'] = 'Odczytuje Twoje oferty w Amazon i zaznacza, dla każdego SKU, czego brakuje w PrestaShop lub co jest tam inne. Porównanie pojawia się poniżej. Do PrestaShop nic jeszcze nie jest zapisywane.';
$_MODULE['<{amazonmarketplacepro}prestashop>configure_35ed5077b53753fe6892726329a04f98'] = 'Wybierz, co zrobić z porównaniem. A tworzy to, czego brakuje w PrestaShop; B zmienia to, co już tam jest.';
