$_MODULE['<{amazonmarketplacepro}prestashop>configure_f09455b329365f7fdf49ea763abc10d0'] = 'Stan feedu';
$_MODULE['<{amazonmarketplacepro}prestashop>configure_de64a1d2acd922dc141be655d48fa0c0'] = 'Wysyłka powyżej 25 SKU trafia do Amazon jako jeden dokument feedu, który Amazon przetwarza w tle, zamiast odpowiadać od razu. Sprawdź tutaj, czy się zakończyła i co zostało odrzucone. Mniejsze wysyłki otrzymują odpowiedź natychmiast pod przyciskiem wysyłki.';
